/**
 * 📚 FreeWebNovel Source
 *
 * Uses ParsedHttpSource with KSP annotations for filters/commands.
 * Custom fetch logic required due to different selectors per listing type.
 */
@Extension
@AutoSourceId(seed = "FreeWebNovel")
@GenerateFilters(title = true, sort = true, sortOptions = ["Latest", "Popular", "New Novels"])
@GenerateCommands(detailFetch = true, chapterFetch = true, contentFetch = true)
@GenerateTests(
    unitTests = true,
    integrationTests = false,
    "status",
    1
)
@TestFixture(
    "https://freewebnovel.com/novel/follow-the-path-of-dao-from-infancy",
    chapterUrl = "https://freewebnovel.com/novel/follow-the-path-of-dao-from-infancy/chapter-1575",
    expectedAuthor = "Ancient Xi",
    expectedTitle = "Follow the path of Dao from infancy"
)
@TestExpectations()
abstract class FreeWebNovel(deps: Dependencies) : ParsedHttpSource(deps) {

    override val name = "FreeWebNovel"
    override val id: Long get() = 4
    override val baseUrl = "https://freewebnovel.com"
    override val lang = "en"

    override fun getFilters(): FilterList = listOf(
        Filter.Title(),
        Filter.Sort("Sort By:", arrayOf("Latest", "Popular", "New Novels")),
    )

    override fun getCommands(): CommandList = listOf(
        Command.Detail.Fetch(),
        Command.Chapter.Fetch(),
        Command.Content.Fetch(),
    )

    override fun getListings(): List<Listing> = listOf(PopularListing(), LatestListing(), NewNovelsListing())
    class PopularListing : Listing("Popular")
    class LatestListing : Listing("Latest")
    class NewNovelsListing : Listing("New Novels")

    override suspend fun getMangaList(sort: Listing?, page: Int): MangasPageInfo {
        return when (sort?.name) {
            "Popular" -> getPopular(page)
            "Latest" -> getLatest(page)
            "New Novels" -> getNewNovel(page)
            else -> getLatest(page)
        }
    }

    override suspend fun getMangaList(filters: ireader.core.source.model.FilterList, page: Int): MangasPageInfo {
        val sorts = filters.findInstance<Filter.Sort>()?.value?.index
        val query = filters.findInstance<Filter.Title>()?.value
        if (!query.isNullOrBlank()) return getSearch(query)
        return when (sorts) {
            0 -> getLatest(page)
            1 -> getPopular(page)
            2 -> getNewNovel(page)
            else -> getLatest(page)
        }
    }

    private fun sortUrl(kind: String, page: Int): String {
        val safePage = page.coerceAtLeast(1)
        return if (safePage == 1) "$baseUrl/sort/$kind" else "$baseUrl/sort/$kind/$safePage"
    }

    private suspend fun getLatest(page: Int): MangasPageInfo {
        val resp = client.get(requestBuilder(sortUrl("latest-release", page)))
        return bookListParse(resp.asJsoup(), "div.ul-list1 div.li-row", "div.ul-list1") { latestFromElement(it) }
    }

    private suspend fun getPopular(page: Int): MangasPageInfo {
        val resp = client.get(requestBuilder(sortUrl("most-popular", page)))
        return bookListParse(resp.asJsoup(), "div.ul-list1 div.li-row", "div.ul-list1") { latestFromElement(it) }
    }


    private suspend fun getSearch(query: String): MangasPageInfo {
//        val resp = client.submitForm(
//            url = "https://freewebnovel.com/search",
//            formParameters = Parameters.build {
//                append("searchkey", query)
//            }
//        ) {
//            headersBuilder()
//        }.asJsoup()
        val resp = client.get(requestBuilder("$baseUrl/search?keyword=$query")).asJsoup()
        return bookListParse(resp, "div.ul-list1 div.li-row", null) { searchFromElement(it) }
    }

    private suspend fun getNewNovel(page: Int): MangasPageInfo {
        val resp = client.get(requestBuilder(sortUrl("latest-novel", page)))
        return bookListParse(resp.asJsoup(), "div.ul-list1 div.li-row", "div.ul-list1") { latestFromElement(it) }
    }

    private fun latestFromElement(element: Element) = MangaInfo(
        key = baseUrl + element.select("div.txt a").attr("href"),
        title = element.select("div.txt a").attr("title"),
        cover = baseUrl + element.select("div.pic img").attr("src")
    )

    private fun searchFromElement(element: Element) = MangaInfo(
        key = baseUrl + element.select("div.txt a").attr("href"),
        title = element.select("div.txt a").attr("title"),
        cover = baseUrl + element.select("div.pic img").attr("src")
    )

    override fun detailParse(document: Document) = MangaInfo(
        title = document.select("div.m-desc h1.tit").text(),
        cover = baseUrl + document.select("div.m-book1 div.pic img").attr("src"),
        description = document.select("div.inner p").eachText().joinToString("\n"),
        author = document.select("div.right a.a1").attr("title"),
        genres = next(document.select("[title=Genre]")).text().split(",").map { it.trim() },
        key = baseUrl + document.select("div.cur div.wp a:nth-child(5)").attr("href"),
        status = next(document.select("[title=Status]")).text().handleStatus()
    )

    private fun String.handleStatus(): Long = when (this) {
        "OnGoing" -> MangaInfo.ONGOING
        "Complete" -> MangaInfo.COMPLETED
        else -> MangaInfo.ONGOING
    }

    override fun chaptersRequest(book: MangaInfo) = HttpRequestBuilder().apply {
        url(book.key)
        headers { headers }
    }

    override fun chaptersSelector() = "div.m-newest2 ul.ul-list5 li"

    override fun chapterFromElement(element: Element) = ChapterInfo(
        name = element.select("a").attr("title"),
        key = baseUrl + element.select("a").attr("href").substringAfter(baseUrl)
    )

    override suspend fun getChapterList(manga: MangaInfo, commands: List<Command<*>>): List<ChapterInfo> =
        withContext(DefaultDispatcher) {
            val chapters = mutableListOf<ChapterInfo>()
            val baseUrl = manga.key
            var page = 1
            var totalPage = 1
            do {
                val response = client.get("$baseUrl?ajax=chapters&page=$page&pageSize=200")
                val json = Json.parseToJsonElement(response.bodyAsText()).jsonObject
                totalPage = json["totalPage"]?.jsonPrimitive?.int ?: 1
                val html = json["html"]?.jsonPrimitive?.content ?: ""
                val doc = Ksoup.parse("<ul>$html</ul>")
                doc.select("li").forEach { element ->
                    val a = element.select("a")
                    chapters.add(
                        ChapterInfo(
                            name = a.attr("title").ifBlank { a.text() },
                            key = (baseUrl.substringBeforeLast("/") + a.attr("href")).replaceFirst("novel/","")
                        )
                    )
                }
                page++
            } while (page <= totalPage)
            chapters
        }

    override fun pageContentParse(document: Document): List<String> =
        document.select("div.txt #article h4,div.txt #article p").eachText()

    override fun contentRequest(chapter: ChapterInfo) = HttpRequestBuilder().apply {
        url(chapter.key)
        headers { headers }
    }
}
